-- CDM-30786 - Child Removal and OOH dates Discrepancies
/*
-- Issue Description: 
   To fix Child Removal, OOH and IV-E dates Discrepancies
 	
-- Category/ Module: Placements  (Case Management) 
-- Root cause: Application code was havign a flaw in te logic for updating OOH & IV-E dates upon Child Removal date changes 
-- Fix Provided: Code fix and the one time Datafix has been promoted to fix the dates discrepancies. 
-- Pull request# N/A
-- Reason why no related code fix: N/A
-- Status of the code fix if already submitted and expected prod fix date: N/A
*/

-- Delete OOH with NO Service case IDs 
select personprogramid, programkey, startdate, enddate, activeflag, updatedby, updatedon
	from personprogramarea 
where activeflag = 1
	and programkey = 'OOH' 
 	and objectid is null ;
	
update personprogramarea
set activeflag = 0,
	updatedby = 'CDM-30786',
	updatedon = now()
where activeflag = 1
	and programkey = 'OOH' 
 	and objectid is null ;
	
